import{_ as o,r as e,o as p,c,e as a,a as i,s as l}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Available Exceptions - October CMS - 4.x","titleTemplate":false,"description":"October CMS comes with several basic exception types out of the box.","frontmatter":{"subtitle":"October CMS comes with several basic exception types out of the box."},"headers":[{"level":3,"title":"Application Exception","slug":"application-exception","link":"#application-exception","children":[]},{"level":3,"title":"System Exception","slug":"system-exception","link":"#system-exception","children":[]},{"level":3,"title":"Not Found Exception","slug":"not-found-exception","link":"#not-found-exception","children":[]},{"level":3,"title":"Validation Exception","slug":"validation-exception","link":"#validation-exception","children":[]},{"level":3,"title":"AJAX Exception","slug":"ajax-exception","link":"#ajax-exception","children":[]},{"level":2,"title":"Exception Handling","slug":"exception-handling","link":"#exception-handling","children":[{"level":3,"title":"Where to Place Error Handlers","slug":"where-to-place-error-handlers","link":"#where-to-place-error-handlers","children":[]}]},{"level":2,"title":"HTTP Exceptions","slug":"http-exceptions","link":"#http-exceptions","children":[{"level":3,"title":"Custom Error Page","slug":"custom-error-page","link":"#custom-error-page","children":[]}]}],"relativePath":"4.x/extend/system/exceptions.md","filePath":"4.x/extend/system/exceptions.md"}'),r={name:"4.x/extend/system/exceptions.md"};function d(u,n,h,k,g,x){const s=e("pre-heading"),t=e("post-heading");return p(),c("div",null,[a(s),n[0]||(n[0]=i("h1",null,"Available Exceptions",-1)),a(t),n[1]||(n[1]=l(`<h3 id="application-exception"><a href="#application-exception" class="header-anchor">#</a> Application Exception</h3><p>The <code>October\\Rain\\Exception\\ApplicationException</code> class, aliased as <code>ApplicationException</code>, is the most common exception type that is used when a simple application condition has failed.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">ApplicationException</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;You must be logged in to do that!&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The error message will be simplified and will never include any sensitive information like the PHP file and line number.</p><h3 id="system-exception"><a href="#system-exception" class="header-anchor">#</a> System Exception</h3><p>The <code>October\\Rain\\Exception\\SystemException</code> class, aliased as <code>SystemException</code>, is used for errors that are critical to the system functioning and are always logged.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">SystemException</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Unable to contact the mail server API&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>When this exception is thrown a detailed error message is shown with the file and line number where it occurred.</p><h3 id="not-found-exception"><a href="#not-found-exception" class="header-anchor">#</a> Not Found Exception</h3><p>The <code>October\\Rain\\Exception\\NotFoundException</code> class, aliased as <code>NotFoundException</code>, is used for errors that occur when a missing record is encountered.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">NotFoundException</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Record not found&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>When this exception is thrown the standard response will change to display the nearest not found page with a 404 status code added.</p><h3 id="validation-exception"><a href="#validation-exception" class="header-anchor">#</a> Validation Exception</h3><p>The <code>October\\Rain\\Exception\\ValidationException</code> class, aliased as <code>ValidationException</code>, is used for errors that relate directly to a form submission and an invalid field. The message should contain an array with fields and error messages.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">ValidationException</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;username&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Sorry that username is already taken!&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You can also pass an instance of the <a href="./../services/validation.html">validation service</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$validation</span> <span class="token operator">=</span> <span class="token class-name static-context">Validator</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$validation</span><span class="token operator">-&gt;</span><span class="token function">fails</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">ValidationException</span><span class="token punctuation">(</span><span class="token variable">$validation</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>When this exception is thrown the <a href="./ajax.html">AJAX framework</a> will provide this information in a usable format and focus the first invalid field.</p><h3 id="ajax-exception"><a href="#ajax-exception" class="header-anchor">#</a> AJAX Exception</h3><p>The <code>October\\Rain\\Exception\\AjaxException</code> class, aliased as <code>AjaxException</code>, is considered a &quot;smart error&quot; and will return the HTTP code 406. This allows them to pass response contents as if they were a successful response.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">AjaxException</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;#flashMessages&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>When this exception is thrown the <a href="./ajax.html">AJAX framework</a> will follow the standard error workflow but will also refresh specified partials.</p><h2 id="exception-handling"><a href="#exception-handling" class="header-anchor">#</a> Exception Handling</h2><p>All exceptions are handled by the <code>October\\Rain\\Foundation\\Exception\\Handler</code> class. This class contains two methods: <code>report</code> and <code>render</code> that dictate if an error should be logged and how to respond to an error.</p><p>However, you may specify custom handlers if needed using the <code>App::error</code> method. Handlers are called based on the type-hint of the Exception they handle. For example, you may create a handler that only handles <code>RuntimeException</code> instances:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token class-name type-declaration">RuntimeException</span> <span class="token variable">$exception</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Handle the exception...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>If an exception handler returns a response, that response will be sent to the browser and no other error handlers will be called.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token class-name type-declaration">InvalidUserException</span> <span class="token variable">$exception</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;Sorry! Something is wrong with this account!&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To listen for PHP fatal errors, you may use check for the Error exception type:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token class-name type-declaration">Error</span> <span class="token variable">$exception</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>If you have several exception handlers, they should be defined from most generic to most specific. So, for example, a handler that handles all exceptions of type <code>Exception</code> should be defined before a custom exception type such as <code>SystemException</code>.</p><h3 id="where-to-place-error-handlers"><a href="#where-to-place-error-handlers" class="header-anchor">#</a> Where to Place Error Handlers</h3><p>Error handler registrations generally fall under the category of bootstrap code. In other words, they prepare your application to actually handle requests, and usually need to be executed before a route or controller is actually called. The most common place is the <code>boot</code> method of a <a href="./../extending.html">plugin registration file</a>. Alternatively, plugins can supply a file named <strong>init.php</strong> in the plugin directory that you can use to place error handler registrations.</p><h2 id="http-exceptions"><a href="#http-exceptions" class="header-anchor">#</a> HTTP Exceptions</h2><p>Some exceptions describe HTTP error codes from the server. For example, this may be a &quot;page not found&quot; error (404), an &quot;unauthorized error&quot; (401) or even a developer generated 500 error. In order to generate such a response from anywhere in your application, use the following.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">abort</span><span class="token punctuation">(</span><span class="token number">404</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The <code>abort</code> method will immediately raise an exception which will be rendered by the exception handler. Optionally, you may provide the response text.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">abort</span><span class="token punctuation">(</span><span class="token number">403</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Unauthorized action.&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>This method may be used at any time during the request&#39;s life cycle. There is also an accompanying <a href="./../../markup/function/abort.html">Twig filter for aborting requests</a>.</p><h3 id="custom-error-page"><a href="#custom-error-page" class="header-anchor">#</a> Custom Error Page</h3><p>By default any errors will be shown with a detailed error page containing the file contents, line number and stack trace where the error occurred. You can display a custom error page by setting the configuration value <code>debug</code> to <strong>false</strong> in the <code>config/app.php</code> script and creating a page with the URL <code>/error</code>.</p>`,41))])}const y=o(r,[["render",d]]);export{f as __pageData,y as default};
